import os
import re

ROMAN_RE = re.compile(r'M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})')
VALS = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'),
        (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
SINGLE = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def to_roman(n):
    out = []
    for v, s in VALS:
        while n >= v:
            out.append(s)
            n -= v
    return ''.join(out)


def from_roman(s):
    total = 0
    for i, ch in enumerate(s):
        v = SINGLE[ch]
        if i + 1 < len(s) and SINGLE[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(s):
    if re.fullmatch(r'[0-9]+', s):
        n = int(s)
        if 1 <= n <= 3999:
            return to_roman(n)
        return 'invalid'
    if re.fullmatch(r'[IVXLCDM]+', s) and ROMAN_RE.fullmatch(s):
        return str(from_roman(s))
    return 'invalid'


def main():
    d = os.environ.get('INPUT', 'input')
    path = os.path.join(d, 'numbers.txt')
    try:
        with open(path, encoding='utf-8', errors='replace') as f:
            lines = f.read().splitlines()
    except OSError:
        return
    for line in lines:
        s = line.strip()
        if not s:
            continue
        print(f"{s} = {convert(s)}")


