import os


def check(line):
    pairs = {'(': ')', '[': ']', '{': '}'}
    closers = set(pairs.values())
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closers:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            exp = stack.pop()
            if exp != ch:
                return "col %d: expected %s, found %s" % (i, exp, ch)
    if stack:
        return "unclosed %s" % stack[-1]
    return "ok"


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "snippets.txt"), encoding="ascii", errors="replace", newline="") as f:
        data = f.read()
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for ln in lines:
        if ln.endswith("\r"):
            ln = ln[:-1]
        out.append(check(ln))
    if out:
        print("\n".join(out))


