import os
import re
import sys

def main():
    d = os.environ.get("INPUT", "")
    path = os.path.join(d, "timings.log")
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        return
    pat = re.compile(rb"^[+-]?[0-9]+$")
    groups = {}
    for line in data.split(b"\n"):
        parts = line.split()
        if len(parts) != 3:
            continue
        m, p, ms = parts
        if not pat.match(ms):
            continue
        groups.setdefault((m, p), []).append(int(ms))
    out = []
    for key in sorted(groups):
        t = sorted(groups[key])
        n = len(t)
        def pct(P):
            return t[(P * n + 99) // 100 - 1]
        out.append(key[0] + b" " + key[1] +
                   (" count=%d p50=%d p95=%d max=%d" % (n, pct(50), pct(95), t[-1])).encode())
    if out:
        sys.stdout.buffer.write(b"\n".join(out) + b"\n")
        sys.stdout.buffer.flush()

