import os
import sys
import heapq


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "routes.txt"), encoding="utf-8", errors="surrogateescape") as f:
        lines = f.read().splitlines()

    adj = {}
    trips = []
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        p = s.split()
        if p[0] == "road" and len(p) == 4:
            try:
                c = int(p[3])
            except ValueError:
                continue
            a, b = p[1], p[2]
            adj.setdefault(a, []).append((b, c))
            adj.setdefault(b, []).append((a, c))
        elif p[0] == "trip" and len(p) == 3:
            trips.append((p[1], p[2]))

    cache = {}

    def dists(t):
        if t in cache:
            return cache[t]
        d = {t: 0}
        h = [(0, t)]
        while h:
            du, u = heapq.heappop(h)
            if du > d.get(u, float("inf")):
                continue
            for v, w in adj.get(u, ()):
                nd = du + w
                if nd < d.get(v, float("inf")):
                    d[v] = nd
                    heapq.heappush(h, (nd, v))
        cache[t] = d
        return d

    out = []
    for x, y in trips:
        if x == y:
            out.append("%s 0" % x)
            continue
        d = dists(y)
        if x not in d:
            out.append("%s %s unreachable" % (x, y))
            continue
        path = [x]
        cur = x
        while cur != y:
            best = None
            for v, w in adj[cur]:
                if v in d and w + d[v] == d[cur]:
                    if best is None or v.encode("utf-8", "surrogateescape") < best.encode("utf-8", "surrogateescape"):
                        best = v
            path.append(best)
            cur = best
        out.append("%s %d" % (" -> ".join(path), d[x]))

    sys.stdout.write("".join(l + "\n" for l in out))


