import os


def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]
    buckets = {"error": [], "warn": [], "info": []}
    other = 0
    with open(os.path.join(inp, "app.log"), "r", encoding="utf-8",
              errors="surrogateescape", newline="\n") as f:
        data = f.read()
    for line in data.split("\n"):
        if line.strip() == "":
            continue
        parts = line.split(" ", 2)
        if len(parts) < 3:
            other += 1
            continue
        lvl = parts[1].upper()
        if lvl == "ERROR":
            buckets["error"].append(line)
        elif lvl in ("WARN", "WARNING"):
            buckets["warn"].append(line)
        elif lvl == "INFO":
            buckets["info"].append(line)
        else:
            other += 1
    for name, lines in buckets.items():
        with open(os.path.join(out, name + ".log"), "w", encoding="utf-8",
                  errors="surrogateescape", newline="\n") as f:
            for l in lines:
                f.write(l + "\n")
    print("error %d" % len(buckets["error"]))
    print("warn %d" % len(buckets["warn"]))
    print("info %d" % len(buckets["info"]))
    print("other %d" % other)


