import os
import json
from collections import Counter


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    totals = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                totals = {str(k): int(v) for k, v in data.items()}
        except (ValueError, OSError):
            totals = {}

    new = Counter()
    visits = os.path.join(input_dir, "visits.txt")
    if os.path.exists(visits):
        with open(visits, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                page = line.strip()
                if page:
                    new[page] += 1

    for page, n in new.items():
        totals[page] = totals.get(page, 0) + n

    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(totals, f)
        f.flush()
        os.fsync(f.fileno())

    items = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0].encode("utf-8")))
    out = "".join("%s %d\n" % (p, t) for p, t in items)
    os.write(1, out.encode("utf-8", errors="replace")) if out else None


