import os
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]

    users = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                users = data
        except Exception:
            users = {}

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8", errors="replace") as f:
        text = f.read()

    out = []
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        n = len(parts)
        if cmd == "put" and n == 4:
            users[parts[1]] = {"name": parts[2], "email": parts[3]}
            out.append("ok " + parts[1])
        elif cmd == "rename" and n == 3:
            i = parts[1]
            if i in users:
                users[i]["name"] = parts[2]
                out.append("ok " + i)
            else:
                out.append("missing " + i)
        elif cmd == "get" and n == 2:
            i = parts[1]
            if i in users:
                u = users[i]
                out.append(json.dumps({"id": i, "name": u["name"], "email": u["email"]},
                                      separators=(",", ":")))
            else:
                out.append("missing " + i)
        elif cmd == "del" and n == 2:
            i = parts[1]
            if i in users:
                del users[i]
                out.append("ok " + i)
            else:
                out.append("missing " + i)
        elif cmd == "count" and n == 1:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(users, f)

    if out:
        print("\n".join(out))


