import os, sys, json


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]

    applied = {}
    balances = {}
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        applied = {k: True for k in data.get("applied", [])}
        balances = dict(data.get("balances", {}))
    except FileNotFoundError:
        pass

    n_applied = n_dup = n_rej = 0
    try:
        with open(os.path.join(input_dir, "events.jsonl"), "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        raw = b""

    for line in raw.split(b"\n"):
        if not line.strip():
            continue
        try:
            obj = json.loads(line.decode("utf-8"))
        except (ValueError, RecursionError):
            n_rej += 1
            continue
        if not isinstance(obj, dict):
            n_rej += 1
            continue
        i = obj.get("id")
        a = obj.get("account")
        c = obj.get("cents")
        if (not isinstance(i, str) or not isinstance(a, str)
                or not isinstance(c, int) or isinstance(c, bool)):
            n_rej += 1
            continue
        if i in applied:
            n_dup += 1
            continue
        applied[i] = True
        balances[a] = balances.get(a, 0) + c
        n_applied += 1

    payload = json.dumps({"applied": list(applied.keys()), "balances": balances})
    tmp = state_path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, state_path)
    except OSError:
        with open(state_path, "w", encoding="utf-8") as f:
            f.write(payload)

    out = ["applied %d duplicate %d rejected %d" % (n_applied, n_dup, n_rej)]
    for k in sorted(balances, key=lambda s: s.encode("utf-8", "surrogatepass")):
        out.append("%s %d" % (k, balances[k]))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))
    sys.stdout.buffer.flush()


main()

import os
import json


def parse_int(tok):
    if "_" in tok:
        return None
    try:
        return int(tok)
    except ValueError:
        return None


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["LIMITS"]

    counts = {}
    try:
        with open(kv_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            for k, v in data.items():
                if isinstance(v, int):
                    counts[k] = v
    except (OSError, ValueError):
        counts = {}

    out = []
    path = os.path.join(input_dir, "requests.txt")
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        lines = []

    max_window = None
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            continue
        ts = parse_int(parts[0])
        if ts is None:
            continue
        client = parts[1]
        window = ts // 60
        key = json.dumps([client, window])
        c = counts.get(key, 0)
        if c < 3:
            counts[key] = c + 1
            out.append("%d %s allow" % (ts, client))
        else:
            out.append("%d %s deny" % (ts, client))
        if max_window is None or window > max_window:
            max_window = window

    # prune windows older than the previous minute relative to latest seen
    if max_window is not None:
        pruned = {}
        for k, v in counts.items():
            try:
                w = json.loads(k)[1]
            except (ValueError, IndexError, TypeError):
                continue
            if w >= max_window - 1:
                pruned[k] = v
        counts = pruned

    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(counts, f)

    if out:
        print("\n".join(out))


main()

import os, json

def main():
    inp = os.environ["INPUT"]
    board_path = os.environ["BOARD"]
    board = {}
    try:
        with open(board_path, "r", encoding="utf-8") as f:
            board = json.load(f)
    except (FileNotFoundError, ValueError):
        board = {}
    if not isinstance(board, dict):
        board = {}

    try:
        with open(os.path.join(inp, "games.txt"), "rb") as f:
            data = f.read().decode("utf-8", errors="surrogateescape")
    except FileNotFoundError:
        data = ""

    def add(name, pts):
        rec = board.get(name)
        if not rec:
            rec = [0, 0]
        rec[0] += pts
        rec[1] += 1
        board[name] = rec

    for line in data.split("\n"):
        parts = line.split()
        if len(parts) == 2:
            add(parts[0], 3)
            add(parts[1], 0)
        elif len(parts) == 3 and parts[2] == "draw":
            add(parts[0], 1)
            add(parts[1], 1)

    with open(board_path, "w", encoding="utf-8") as f:
        json.dump(board, f)

    ranked = sorted(
        board.items(),
        key=lambda kv: (-kv[1][0], kv[1][1], kv[0].encode("utf-8", "surrogateescape")),
    )
    out = []
    for i, (name, (pts, played)) in enumerate(ranked[:3], 1):
        out.append("%d. %s %d %d" % (i, name, pts, played))
    if out:
        import sys
        sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogateescape"))

