import os
import sqlite3


def parse_move(line):
    parts = line.split()
    if len(parts) != 2:
        return None
    sku, tok = parts
    if len(tok) < 2 or tok[0] not in "+-":
        return None
    d = tok[1:]
    if not (d.isascii() and d.isdigit()):
        return None
    n = int(d)
    if n <= 0:
        return None
    return sku, (n if tok[0] == "+" else -n)


def main():
    input_dir = os.environ["INPUT"]
    db_path = os.environ["STOCK"]
    try:
        with open(os.path.join(input_dir, "moves.txt"), "rb") as f:
            text = f.read().decode("utf-8", "replace")
    except FileNotFoundError:
        text = ""

    batches = []
    cur = None
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "batch" and len(parts) == 2:
            cur = [parts[1], [], False]
            batches.append(cur)
            continue
        if cur is None:
            continue
        m = parse_move(line)
        if m is None:
            cur[2] = True
        else:
            cur[1].append(m)

    con = sqlite3.connect(db_path, isolation_level=None)
    con.execute("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)")
    con.execute("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)")

    out = []
    for name, moves, bad in batches:
        con.execute("BEGIN IMMEDIATE")
        try:
            if con.execute("SELECT 1 FROM applied WHERE name=?", (name,)).fetchone():
                con.execute("ROLLBACK")
                out.append(f"{name} skipped")
                continue
            if bad:
                con.execute("ROLLBACK")
                out.append(f"{name} rejected")
                continue
            local = {}
            ok = True
            for sku, d in moves:
                if sku not in local:
                    r = con.execute("SELECT qty FROM stock WHERE sku=?", (sku,)).fetchone()
                    local[sku] = r[0] if r else 0
                local[sku] += d
                if local[sku] < 0:
                    ok = False
                    break
            if not ok:
                con.execute("ROLLBACK")
                out.append(f"{name} rejected")
                continue
            for sku, q in local.items():
                con.execute(
                    "INSERT INTO stock(sku, qty) VALUES(?, ?) "
                    "ON CONFLICT(sku) DO UPDATE SET qty=excluded.qty",
                    (sku, q),
                )
            con.execute("INSERT INTO applied(name) VALUES(?)", (name,))
            con.execute("COMMIT")
            out.append(f"{name} applied")
        except BaseException:
            try:
                con.execute("ROLLBACK")
            except Exception:
                pass
            raise

    rows = con.execute("SELECT sku, qty FROM stock WHERE qty != 0").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, q in rows:
        out.append(f"{sku} {q}")
    con.close()
    print("\n".join(out))


main()

import os
import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ["STORE"]
LOCK = threading.Lock()


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict) and isinstance(d.get("todos"), list):
            d.setdefault("next", max([t["id"] for t in d["todos"]] + [0]) + 1)
            return d
    except Exception:
        pass
    return {"next": 1, "todos": []}


def save(d):
    with open(STORE, "w", encoding="utf-8") as f:
        json.dump(d, f)
        f.flush()
        os.fsync(f.fileno())


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        body = b"" if obj is None else json.dumps(obj).encode()
        self.send_response(code)
        if obj is not None:
            self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def nf(self):
        self.send(404, {"error": "not found"})

    def read_json(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        try:
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def handle_any(self):
        method = self.command
        # always consume body so the connection stays in sync
        body = self.read_json() if method in ("POST", "PATCH", "PUT", "DELETE") else None
        u = urlsplit(self.path)
        parts = u.path.split("/")
        with LOCK:
            d = load()
            todos = d["todos"]
            if u.path == "/todos":
                if method == "POST":
                    t = body.get("title") if isinstance(body, dict) else None
                    if not isinstance(t, str) or not t.strip():
                        return self.send(400, {"error": "title required"})
                    todo = {"id": d["next"], "title": t.strip(), "done": False}
                    d["next"] += 1
                    todos.append(todo)
                    save(d)
                    return self.send(201, todo)
                if method == "GET":
                    q = parse_qs(u.query).get("done")
                    out = sorted(todos, key=lambda x: x["id"])
                    if q:
                        if q[-1] == "true":
                            out = [x for x in out if x["done"]]
                        elif q[-1] == "false":
                            out = [x for x in out if not x["done"]]
                    return self.send(200, out)
                return self.nf()
            if len(parts) == 3 and parts[0] == "" and parts[1] == "todos":
                s = parts[2]
                if not (s.isascii() and s.isdigit() and str(int(s)) == s):
                    return self.nf()
                tid = int(s)
                todo = next((x for x in todos if x["id"] == tid), None)
                if todo is None:
                    return self.nf()
                if method == "GET":
                    return self.send(200, todo)
                if method == "DELETE":
                    d["todos"] = [x for x in todos if x["id"] != tid]
                    save(d)
                    return self.send(204)
                if method == "PATCH":
                    if not isinstance(body, dict):
                        return self.send(400, {"error": "bad update"})
                    new = {}
                    if "title" in body:
                        t = body["title"]
                        if not isinstance(t, str) or not t.strip():
                            return self.send(400, {"error": "bad update"})
                        new["title"] = t.strip()
                    if "done" in body:
                        if not isinstance(body["done"], bool):
                            return self.send(400, {"error": "bad update"})
                        new["done"] = body["done"]
                    todo.update(new)
                    save(d)
                    return self.send(200, todo)
            return self.nf()

    do_GET = do_POST = do_PATCH = do_DELETE = do_PUT = do_HEAD = do_OPTIONS = handle_any


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H)
    srv.daemon_threads = True
    srv.serve_forever()

import os, json, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)")
lock = threading.Lock()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def nf(self):
        self.send(404, {"error": "not found"})

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        parts = urlsplit(self.path)
        segs = parts.path.split("/")
        m = self.command
        if len(segs) < 2 or segs[0] != "" or segs[1] != "notes" or len(segs) > 3:
            return self.nf()
        nid = None
        if len(segs) == 3:
            s = segs[2]
            if not (s.isascii() and s.isdigit()):
                return self.nf()
            nid = int(s)
        if nid is None:
            if m == "POST":
                return self.create(raw)
            if m == "GET":
                return self.listing(parts.query)
            return self.nf()
        if m == "GET":
            with lock:
                r = conn.execute("SELECT id,title,body,tags FROM notes WHERE id=?", (nid,)).fetchone()
            if not r:
                return self.nf()
            return self.send(200, {"id": r[0], "title": r[1], "body": r[2], "tags": json.loads(r[3])})
        if m == "DELETE":
            with lock:
                c = conn.execute("DELETE FROM notes WHERE id=?", (nid,))
                cnt = c.rowcount
            if cnt < 1:
                return self.nf()
            return self.send(200, {"deleted": nid})
        return self.nf()

    def create(self, raw):
        bad = lambda: self.send(400, {"error": "invalid note"})
        try:
            d = json.loads(raw.decode())
        except Exception:
            return bad()
        if not isinstance(d, dict):
            return bad()
        t, b = d.get("title"), d.get("body")
        tags = d.get("tags", [])
        if not isinstance(t, str) or not t or not isinstance(b, str):
            return bad()
        if not isinstance(tags, list) or not all(isinstance(x, str) for x in tags):
            return bad()
        out = []
        for x in tags:
            x = x.lower()
            if x not in out:
                out.append(x)
        with lock:
            c = conn.execute("INSERT INTO notes (title,body,tags) VALUES (?,?,?)", (t, b, json.dumps(out)))
            nid = c.lastrowid
        self.send(201, {"id": nid})

    def listing(self, query):
        qs = parse_qs(query, keep_blank_values=True)
        tag = qs["tag"][0].lower() if "tag" in qs else None
        q = qs["q"][0] if "q" in qs else None
        with lock:
            rows = conn.execute("SELECT id,title,body,tags FROM notes ORDER BY id DESC").fetchall()
        out = []
        for i, t, b, tg in rows:
            if tag is not None and tag not in json.loads(tg):
                continue
            if q is not None and q not in t and q not in b:
                continue
            out.append({"id": i, "title": t})
        self.send(200, out)

    do_GET = do_POST = do_DELETE = do_PUT = do_PATCH = do_HEAD = do_OPTIONS = handle_any


ThreadingHTTPServer.daemon_threads = True
ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

import os, json

def key(s):
    return s.encode('utf-8', 'surrogatepass')

def main():
    d = os.environ.get("INPUT", "")
    try:
        with open(os.path.join(d, "packages.json"), "rb") as f:
            data = json.loads(f.read().decode("utf-8", "replace"))
    except Exception:
        print("error: not an object")
        return
    if not isinstance(data, dict):
        print("error: not an object")
        return

    valid = {}
    invalid = []
    for k, v in data.items():
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            valid[k] = list(dict.fromkeys(v))
        else:
            invalid.append(k)

    missing = {}
    for p, deps in valid.items():
        for q in deps:
            if q not in valid:
                missing.setdefault(q, []).append(p)

    # Tarjan SCC (iterative) on valid graph
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    counter = 0
    for root in sorted(valid, key=key):
        if root in index:
            continue
        work = [(root, 0)]
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        while work:
            v, i = work.pop()
            deps = [x for x in valid[v] if x in valid]
            if i < len(deps):
                work.append((v, i + 1))
                w = deps[i]
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, 0))
                elif w in onstack:
                    low[v] = min(low[v], index[w])
            else:
                if low[v] == index[v]:
                    comp = []
                    while True:
                        w = stack.pop()
                        onstack.discard(w)
                        comp.append(w)
                        if w == v:
                            break
                    sccs.append(comp)
                if work:
                    u = work[-1][0]
                    low[u] = min(low[u], low[v])

    cycles = []
    incycle = set()
    for c in sccs:
        if len(c) >= 2 or (c[0] in valid[c[0]]):
            cycles.append(sorted(c, key=key))
            incycle.update(c)
    cycles.sort(key=lambda c: key(c[0]))

    stage = {}
    remaining = set(valid)
    rnd = 1
    while True:
        new = []
        for p in remaining:
            if all(q in stage for q in valid[p]):
                new.append(p)
        if not new:
            break
        for p in new:
            stage[p] = rnd
            remaining.discard(p)
        rnd += 1

    out = []
    stages = {}
    for p, s in stage.items():
        stages.setdefault(s, []).append(p)
    for s in sorted(stages):
        out.append("stage %d: %s" % (s, ", ".join(sorted(stages[s], key=key))))
    for c in cycles:
        out.append("cycle: " + ", ".join(c))
    for m in sorted(missing, key=key):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m], key=key))))
    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid, key=key)))
    blocked = [p for p in valid if p not in stage and p not in incycle]
    if blocked:
        out.append("blocked: " + ", ".join(sorted(blocked, key=key)))
    out.append("built %d of %d" % (len(stage), len(valid)))
    print("\n".join(out))

main()

import os, re, sys

def main(input):
    with open(os.path.join(input, "bookings.csv"), "rb") as f:
        data = f.read().decode("utf-8", "replace")
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    tre = re.compile(r"^([0-9]{2}):([0-9]{2})$")

    def parse(t, allow24):
        m = tre.match(t)
        if not m:
            return None
        h, mi = int(m.group(1)), int(m.group(2))
        if mi > 59:
            return None
        if h == 24 and mi == 0 and allow24:
            return 1440
        if h > 23:
            return None
        return h * 60 + mi

    def fmt(x):
        return "%02d:%02d" % (x // 60, x % 60)

    skipped = []
    seen = set()
    groups = {}
    for i, raw in enumerate(lines):
        n = i + 1
        if n == 1:
            continue
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip() == "":
            continue
        f = line.split(",")
        if len(f) != 5:
            skipped.append(n)
            continue
        s = parse(f[2], False)
        e = parse(f[3], True)
        if s is None or e is None or e <= s:
            skipped.append(n)
            continue
        key = tuple(f)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault((f[0], f[1]), []).append((s, e, f[4]))

    bk = lambda x: x.encode("utf-8", "surrogateescape")
    out = []
    for room, day in sorted(groups, key=lambda k: (bk(k[0]), bk(k[1]))):
        bs = groups[(room, day)]
        merged = []
        for s, e, _ in sorted(bs):
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        out.append("%s %s" % (room, day))
        out.append("  busy " + ", ".join("%s-%s" % (fmt(a), fmt(b)) for a, b in merged))
        free = []
        cur = 540
        for a, b in merged:
            if b <= 540:
                continue
            if a >= 1080:
                break
            if a - cur >= 30 and a > cur:
                free.append((cur, min(a, 1080)))
            cur = max(cur, b)
        if cur < 1080 and 1080 - cur >= 30:
            free.append((cur, 1080))
        out.append("  free " + (", ".join("%s-%s" % (fmt(a), fmt(b)) for a, b in free) if free else "none"))
        conf = []
        for x in range(len(bs)):
            for y in range(x + 1, len(bs)):
                lo = max(bs[x][0], bs[y][0])
                hi = min(bs[x][1], bs[y][1])
                if lo < hi:
                    names = sorted([bs[x][2], bs[y][2]], key=bk)
                    conf.append((lo, "  conflict %s/%s %s-%s" % (names[0], names[1], fmt(lo), fmt(hi))))
        conf.sort(key=lambda c: (c[0], bk(c[1])))
        out.extend(c[1] for c in conf)
    out.append("skipped: " + (", ".join(map(str, skipped)) if skipped else "none"))
    sys.stdout.write("\n".join(out) + "\n")

