import os, sys, json
from decimal import Decimal

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass


class F:
    def __init__(self, s):
        self.d = Decimal(s)


def bad_const(s):
    raise ValueError("bad constant")


def parse(text):
    return json.loads(text, parse_float=F, parse_constant=bad_const)


def is_num(v):
    return (isinstance(v, int) and not isinstance(v, bool)) or isinstance(v, F)


def check(v, sch, path, errs):
    t = sch.get("type")
    if t == "object":
        if not isinstance(v, dict):
            errs.append((path, "expected object")); return
        props = sch.get("properties", {}) or {}
        for r in sch.get("required", []) or []:
            if r not in v:
                errs.append((path + "." + r, "missing required field"))
        if sch.get("additional", True) is False:
            for k in v:
                if k not in props:
                    errs.append((path + "." + k, "unexpected field"))
        for k, s in props.items():
            if k in v:
                check(v[k], s, path + "." + k, errs)
    elif t == "array":
        if not isinstance(v, list):
            errs.append((path, "expected array")); return
        mi = sch.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d items" % mi))
        it = sch.get("items")
        if it is not None:
            for i, e in enumerate(v):
                check(e, it, "%s[%d]" % (path, i), errs)
    elif t == "string":
        if not isinstance(v, str):
            errs.append((path, "expected string")); return
        mn = sch.get("min_length"); mx = sch.get("max_length")
        en = sch.get("enum")
        if mn is not None and len(v) < mn:
            errs.append((path, "shorter than %d" % mn))
        elif mx is not None and len(v) > mx:
            errs.append((path, "longer than %d" % mx))
        elif en is not None and v not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        ok = (isinstance(v, int) and not isinstance(v, bool)) if t == "integer" else is_num(v)
        if not ok:
            errs.append((path, "expected " + t)); return
        x = v.d if isinstance(v, F) else v
        mn = sch.get("minimum"); mx = sch.get("maximum")
        if mn is not None and x < mn:
            errs.append((path, "less than %d" % mn))
        elif mx is not None and x > mx:
            errs.append((path, "greater than %d" % mx))
    elif t == "boolean":
        if not isinstance(v, bool):
            errs.append((path, "expected boolean"))
    elif t == "null":
        if v is not None:
            errs.append((path, "expected null"))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "schema.json"), "rb") as f:
        schema = json.loads(f.read().decode("utf-8"))
    with open(os.path.join(d, "records.jsonl"), "rb") as f:
        data = f.read()
    out = []
    total = 0
    valid = 0
    for n, raw in enumerate(data.split(b"\n"), 1):
        if not raw.strip(b" \t\r\f\v"):
            continue
        total += 1
        try:
            rec = parse(raw.decode("utf-8"))
        except (ValueError, RecursionError):
            out.append("line %d: invalid JSON" % n)
            continue
        errs = []
        check(rec, schema, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % n)
        else:
            errs.sort(key=lambda e: (e[0].encode("utf-8", "surrogatepass"),
                                     e[1].encode("utf-8", "surrogatepass")))
            for p, m in errs:
                out.append("line %d: %s: %s" % (n, p, m))
    out.append("valid %d of %d" % (valid, total))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))


