import os, sys, json, urllib.request, urllib.error


def main():
    inp = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")

    state = {}
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            s = json.load(f)
        if isinstance(s, dict):
            state = s
    except Exception:
        state = {}

    with open(os.path.join(inp, "records.jsonl"), "rb") as f:
        data = f.read()

    out = []
    records = {}
    for n, raw in enumerate(data.split(b"\n"), 1):
        text = raw.decode("utf-8", errors="replace").strip()
        if not text:
            continue
        try:
            obj = json.loads(text)
        except Exception:
            obj = None
        if (not isinstance(obj, dict) or not isinstance(obj.get("id"), str)
                or not isinstance(obj.get("version"), int)
                or isinstance(obj.get("version"), bool)):
            out.append("line %d invalid" % n)
            continue
        records[obj["id"]] = obj

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(records, key=lambda x: x.encode("utf-8", errors="surrogatepass")):
        obj = records[rid]
        last = state.get(rid)
        if isinstance(last, int) and obj["version"] <= last:
            out.append("%s unchanged" % rid)
            counts["unchanged"] += 1
            continue
        body = json.dumps(obj).encode("utf-8")
        url = api + "/records/" + urllib.request.quote(rid, safe="")
        result = None
        for _ in range(3):
            status = None
            try:
                req = urllib.request.Request(url, data=body, method="PUT",
                                             headers={"content-type": "application/json"})
                with urllib.request.urlopen(req, timeout=30) as r:
                    status = r.status
            except urllib.error.HTTPError as e:
                status = e.code
            except Exception:
                status = None
            if status is not None and 200 <= status < 300:
                result = ("synced", status)
                break
            if status is not None and 400 <= status < 500:
                result = ("rejected", status)
                break
        if result is None:
            result = ("failed", None)
        if result[0] == "synced":
            state[rid] = obj["version"]
            out.append("%s synced" % rid)
        elif result[0] == "rejected":
            out.append("%s rejected %d" % (rid, result[1]))
        else:
            out.append("%s failed" % rid)
        counts[result[0]] += 1

    try:
        tmp = state_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(state, f)
        os.replace(tmp, state_path)
    except Exception:
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state, f)

    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))
    sys.stdout.write("\n".join(out) + "\n")


main()

import os, re, sqlite3, sys, datetime

MAXV = 9223372036854775807
INT = re.compile(r'-?[0-9]+')


def fmt(ms):
    d = datetime.datetime.fromtimestamp(ms // 1000, datetime.timezone.utc)
    return d.strftime('%Y-%m-%dT%H:%M:%SZ')


def main():
    inp = os.environ['INPUT']
    dbp = os.environ['DB']
    logp = os.environ['LOG']
    now = int(os.environ['CLOCK'])
    ts = fmt(now)

    con = sqlite3.connect(dbp, isolation_level=None)
    con.execute("CREATE TABLE IF NOT EXISTS accounts(name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last INTEGER NOT NULL, closed INTEGER NOT NULL DEFAULT 0)")
    con.execute("CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY, frm TEXT NOT NULL, tto TEXT NOT NULL, cents TEXT NOT NULL)")
    con.execute("BEGIN")

    with open(os.path.join(inp, 'ops.txt'), 'rb') as f:
        text = f.read().decode('utf-8', 'surrogateescape')
    lines = text.split('\n')

    ok = failed = dup = 0
    logs = []

    def get(name):
        r = con.execute("SELECT balance, closed FROM accounts WHERE name=?", (name,)).fetchone()
        return r

    def live(name):
        r = get(name)
        if r is None or r[1]:
            return None
        return r[0]

    for i, raw in enumerate(lines, 1):
        line = raw[:-1] if raw.endswith('\r') else raw
        if line.strip() == '':
            continue
        w = line.split(' ')
        op = w[0]
        err = None
        isdup = False
        if op == 'open' and len(w) == 3 and INT.fullmatch(w[2]):
            name = w[1]
            c = int(w[2])
            if c < 0:
                err = 'bad amount'
            elif get(name) is not None:
                err = 'account exists'
            elif c > MAXV:
                err = 'overflow'
            else:
                con.execute("INSERT INTO accounts(name,balance,last,closed) VALUES(?,?,?,0)", (name, c, now))
        elif op == 'transfer' and len(w) == 5 and INT.fullmatch(w[4]):
            tid, fr, to = w[1], w[2], w[3]
            c = int(w[4])
            prev = con.execute("SELECT frm,tto,cents FROM transfers WHERE id=?", (tid,)).fetchone()
            if prev is not None:
                if prev == (fr, to, str(c)):
                    isdup = True
                else:
                    err = 'id reused'
            if prev is None:
                if c <= 0:
                    err = 'bad amount'
                elif fr == to:
                    err = 'same account'
                else:
                    fb = live(fr)
                    if fb is None:
                        err = 'no account ' + fr
                    else:
                        tb = live(to)
                        if tb is None:
                            err = 'no account ' + to
                        elif fb < c:
                            err = 'insufficient funds'
                        elif tb + c > MAXV:
                            err = 'overflow'
                        else:
                            con.execute("UPDATE accounts SET balance=?, last=? WHERE name=?", (fb - c, now, fr))
                            con.execute("UPDATE accounts SET balance=?, last=? WHERE name=?", (tb + c, now, to))
                            con.execute("INSERT INTO transfers(id,frm,tto,cents) VALUES(?,?,?,?)", (tid, fr, to, str(c)))
        elif op == 'close' and len(w) == 2:
            b = live(w[1])
            if b is None:
                err = 'no account ' + w[1]
            elif b != 0:
                err = 'balance not zero'
            else:
                con.execute("UPDATE accounts SET closed=1 WHERE name=?", (w[1],))
        else:
            err = 'malformed'

        if isdup:
            dup += 1
        elif err:
            failed += 1
            logs.append("%s line %d: %s\n" % (ts, i, err))
        else:
            ok += 1

    rows = con.execute("SELECT name,balance,last FROM accounts WHERE closed=0").fetchall()
    con.execute("COMMIT")
    con.close()

    if logs:
        with open(logp, 'ab') as f:
            f.write(''.join(logs).encode('utf-8', 'surrogateescape'))

    rows.sort(key=lambda r: r[0].encode('utf-8', 'surrogateescape'))
    out = ["ok %d failed %d duplicate %d" % (ok, failed, dup)]
    for n, b, l in rows:
        out.append("%s %d last %s" % (n, b, fmt(l)))
    sys.stdout.buffer.write(('\n'.join(out) + '\n').encode('utf-8', 'surrogateescape'))
    sys.stdout.buffer.flush()


main()

import os, sys, json, re, hashlib, secrets, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV = os.environ["KV"]
NOW = int(os.environ["CLOCK"])
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()
NAME_RE = re.compile(r"[a-z0-9_]{3,20}")

try:
    with open(KV, "r") as f:
        STATE = json.load(f)
except Exception:
    STATE = {}
STATE.setdefault("users", {})
STATE.setdefault("sessions", {})


def save():
    tmp = KV + ".tmp"
    with open(tmp, "w") as f:
        json.dump(STATE, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV)


def hpw(salt, pw):
    return hashlib.sha256(salt.encode() + b":" + pw.encode("utf-8", "surrogatepass")).hexdigest()


def creds(body):
    try:
        d = json.loads(body.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(d, dict):
        return None
    n, p = d.get("name"), d.get("password")
    if not isinstance(n, str) or not isinstance(p, str):
        return None
    return n, p


def handle(method, path, headers, body):
    now = NOW
    users, sessions = STATE["users"], STATE["sessions"]
    if path == "/users" and method == "POST":
        c = creds(body)
        if c is None or not NAME_RE.fullmatch(c[0]) or len(c[1].encode("utf-8", "surrogatepass")) < 8:
            return 400, {"error": "invalid"}
        n, p = c
        if n in users:
            return 409, {"error": "name taken"}
        salt = secrets.token_hex(8)
        users[n] = {"salt": salt, "hash": hpw(salt, p), "fails": 0,
                    "locked_until": 0, "logins": 0}
        save()
        return 201, {"name": n}
    if path == "/login" and method == "POST":
        bad = (401, {"error": "bad credentials"})
