                    "locked_until": 0, "logins": 0}
        save()
        return 201, {"name": n}
    if path == "/login" and method == "POST":
        bad = (401, {"error": "bad credentials"})
        c = creds(body)
        if c is None:
            return bad
        u = users.get(c[0])
        if u is None:
            return bad
        if u["locked_until"] and now < u["locked_until"]:
            return 429, {"error": "locked"}
        if u["locked_until"]:
            u["locked_until"] = 0
            u["fails"] = 0
        if hpw(u["salt"], c[1]) != u["hash"]:
            u["fails"] += 1
            if u["fails"] >= 3:
                u["locked_until"] = now + 900000
                u["fails"] = 0
            save()
            return bad
        u["fails"] = 0
        u["logins"] += 1
        tok = secrets.token_bytes(16).hex()
        sessions[tok] = {"name": c[0], "expires": now + 1800000}
        save()
        return 200, {"token": tok, "expires_in": 1800}
    if path in ("/me", "/logout") and method == ("GET" if path == "/me" else "POST"):
        unauth = (401, {"error": "unauthorized"})
        a = headers.get("authorization", "")
        if not a.startswith("Bearer "):
