            return unauth
        if path == "/me":
            s["expires"] = now + 1800000
            save()
            return 200, {"name": s["name"], "logins": users[s["name"]]["logins"]}
        del sessions[tok]
        save()
        return 204, None
    return 404, {"error": "not found"}


