import os, re, json, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

LOCK = threading.Lock()
conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("PRAGMA journal_mode=WAL")
conn.execute("PRAGMA synchronous=FULL")
conn.execute("""CREATE TABLE IF NOT EXISTS payments(
 n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL,
 currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)""")
conn.execute("""CREATE TABLE IF NOT EXISTS idem(
 k TEXT PRIMARY KEY, method TEXT, path TEXT, body TEXT, status INTEGER, resp TEXT)""")
conn.execute("CREATE INDEX IF NOT EXISTS pay_acc ON payments(account)")


def pay(r):
    return {"id": "pay_%d" % r[0], "account": r[1], "cents": r[2],
            "currency": r[3], "status": r[4], "refunded": r[5]}


def out(status, obj):
    return status, json.dumps(obj)


def err(status, msg):
    return out(status, {"error": msg})


def isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def canon(raw):
    try:
        return json.dumps(json.loads(raw.decode("utf-8")), sort_keys=True)
    except Exception:
        return json.dumps(["__raw__", raw.decode("utf-8", "replace")])


def parsed(raw):
    try:
        return json.loads(raw.decode("utf-8"))
    except Exception:
        return None


def get_pay(n):
    return conn.execute("SELECT * FROM payments WHERE n=?", (n,)).fetchone()


def handle(method, rawpath, headers, raw):
    sp = urlsplit(rawpath)
    path = sp.path
    if method == "GET":
        m = re.fullmatch(r"/payments/pay_([0-9]+)", path)
        if m:
            r = get_pay(int(m.group(1)))
            return out(200, pay(r)) if r else err(404, "not found")
        if path == "/payments":
            acc = parse_qs(sp.query).get("account")
            if not acc:
                return out(200, [])
            rows = conn.execute("SELECT * FROM payments WHERE account=? ORDER BY n", (acc[0],)).fetchall()
            return out(200, [pay(r) for r in rows])
        return err(404, "not found")
    if method != "POST":
        return err(404, "not found")
    m = re.fullmatch(r"/payments/pay_([0-9]+)/(capture|cancel|refund)", path)
    if path == "/payments":
        kind = "create"
    elif m:
        kind = m.group(2)
    else:
        return err(404, "not found")
    needs_key = kind in ("create", "refund")
    key = None
    if needs_key:
        key = headers.get("idempotency-key")
        if key is None or key == "":
            return err(400, "missing idempotency key")
        row = conn.execute("SELECT method,path,body,status,resp FROM idem WHERE k=?", (key,)).fetchone()
        if row:
            if row[0] == method and row[1] == path and row[2] == canon(raw):
                return row[3], row[4]
            return err(409, "key reused")
    body = parsed(raw)
    if kind == "create":
        if (isinstance(body, dict) and set(body) == {"account", "cents", "currency"}
                and isinstance(body["account"], str) and body["account"]
                and isint(body["cents"]) and body["cents"] > 0
                and body["currency"] in ("EUR", "USD")):
            cur = conn.execute("INSERT INTO payments(account,cents,currency,status,refunded) VALUES(?,?,?,?,0)",
                               (body["account"], body["cents"], body["currency"], "pending"))
            result = out(201, pay(get_pay(cur.lastrowid)))
        else:
            return err(422, "invalid payment")
    else:
        n = int(m.group(1))
        r = get_pay(n)
        if not r:
            return err(404, "not found")
        if kind == "capture":
            if r[4] == "pending":
                conn.execute("UPDATE payments SET status='captured' WHERE n=?", (n,))
            elif r[4] != "captured":
                return err(409, "invalid transition")
            result = out(200, pay(get_pay(n)))
        elif kind == "cancel":
            if r[4] != "pending":
                return err(409, "invalid transition")
            conn.execute("UPDATE payments SET status='canceled' WHERE n=?", (n,))
            result = out(200, pay(get_pay(n)))
        else:
            if not (isinstance(body, dict) and set(body) == {"cents"} and isint(body["cents"]) and body["cents"] > 0):
                return err(422, "invalid refund")
            if r[4] != "captured":
                return err(409, "invalid transition")
            total = r[5] + body["cents"]
            if total > r[2]:
                return err(409, "exceeds captured")
            st = "refunded" if total == r[2] else "captured"
            conn.execute("UPDATE payments SET refunded=?, status=? WHERE n=?", (total, st, n))
            result = out(200, pay(get_pay(n)))
    if needs_key and 200 <= result[0] < 300:
        conn.execute("INSERT INTO idem(k,method,path,body,status,resp) VALUES(?,?,?,?,?,?)",
                     (key, method, path, canon(raw), result[0], result[1]))
    return result


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def do(self):
        try:
            ln = int(self.headers.get("content-length") or 0)
        except ValueError:
            ln = 0
        raw = self.rfile.read(ln) if ln > 0 else b""
        hdrs = {k.lower(): v for k, v in self.headers.items()}
        with LOCK:
            try:
                conn.execute("BEGIN IMMEDIATE")
                status, text = handle(self.command, self.path, hdrs, raw)
                conn.execute("COMMIT")
            except Exception:
                try:
                    conn.execute("ROLLBACK")
                except Exception:
                    pass
                status, text = 500, json.dumps({"error": "internal error"})
        data = text.encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = do


ThreadingHTTPServer.daemon_threads = True
ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

import os, sys, re, json, hashlib

WORD = re.compile(rb'[^\x00-\x2f\x3a-\x40\x5b-\x60\x7b-\x7f]+')


def words_of(data):
    return [w.decode('utf-8', 'replace').lower() for w in WORD.findall(data)]


def main():
    docs = os.environ['DOCS']
    queries = os.environ['QUERIES']
    kv = os.environ['INDEX']

    old = {}
    try:
        with open(kv, 'r', encoding='utf-8') as f:
            st = json.load(f)
        old = st['files']
    except Exception:
        old = {}

    cur = {}
    paths = []
    for root, dirs, files in os.walk(docs):
        for n in files:
            full = os.path.join(root, n)
            if not os.path.isfile(full):
                continue
            rel = os.path.relpath(full, docs).replace(os.sep, '/')
            paths.append((rel, full))

    out = []
    unchanged = 0
    seen = set()
    for rel, full in paths:
        try:
            with open(full, 'rb') as f:
                data = f.read()
        except OSError:
            continue
        seen.add(rel)
        h = hashlib.sha256(data).hexdigest()
        o = old.get(rel)
        if o is None:
            out.append((rel, 'added'))
            cur[rel] = {'h': h, 'w': sorted(set(words_of(data)))}
        elif o.get('h') != h:
            out.append((rel, 'changed'))
            cur[rel] = {'h': h, 'w': sorted(set(words_of(data)))}
        else:
            unchanged += 1
            cur[rel] = o
    for rel in old:
        if rel not in seen:
            out.append((rel, 'removed'))

    key = lambda p: os.fsencode(p)
    out.sort(key=lambda x: key(x[0]))

    # inverted index
    inv = {}
    for rel, e in cur.items():
        for w in e['w']:
            inv.setdefault(w, set()).add(rel)

    with open(kv, 'w', encoding='utf-8') as f:
        json.dump({'files': cur}, f)

    buf = []
    for rel, kind in out:
        buf.append(os.fsencode(kind + ' ' + rel) + b'\n')
    buf.append(('unchanged %d\n' % unchanged).encode())

    try:
        with open(os.path.join(queries, 'queries.txt'), 'rb') as f:
            qdata = f.read()
    except OSError:
        qdata = b''
    text = qdata.decode('utf-8', 'replace')
    allpaths = set(cur)
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        ws = words_of(line.encode('utf-8', 'surrogateescape'))
        res = None
        for w in ws:
            s = inv.get(w, set())
            res = set(s) if res is None else res & s
            if not res:
                break
        if res is None:
            res = set(allpaths)
        if res:
            r = ', '.join(sorted(res, key=key))
        else:
            r = 'none'
        buf.append(os.fsencode(line + ': ' + r) + b'\n')

    sys.stdout.buffer.write(b''.join(buf))
    sys.stdout.buffer.flush()


main()

import os, sys, json, sqlite3, urllib.request, urllib.error, urllib.parse


def isint(x):
    return isinstance(x, int) and not isinstance(x, bool)


def valid(c):
    if not isinstance(c, dict):
        return False
    op = c.get("op")
    if not isinstance(c.get("sku"), str) or not isint(c.get("version")):
        return False
    if op == "upsert":
        return isinstance(c.get("name"), str) and isint(c.get("qty"))
    return op == "delete"


def fetch(base, cursor):
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(cursor, safe="")
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            status = r.status
            body = r.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None)
    nxt = data.get("next")
    if nxt is not None and not (isinstance(nxt, str) or isint(nxt)):
        return ("invalid", None)
    return ("ok", data)


def main():
    base = os.environ["API"]
    conn = sqlite3.connect(os.environ["DB"], isolation_level=None)
    conn.execute("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, version INTEGER NOT NULL, name TEXT, qty INTEGER, present INTEGER NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT)")
    row = conn.execute("SELECT v FROM meta WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    outcome = "complete"
    while True:
        kind, data = fetch(base, cursor)
        if kind == "status":
            outcome = "stopped at %s (status %d)" % (cursor, data)
            break
        if kind == "invalid":
            outcome = "stopped at %s (invalid page)" % cursor
            break
        if kind == "noresp":
            outcome = "stopped at %s (no response)" % cursor
            break
        a = s = i = 0
        conn.execute("BEGIN")
        try:
            for c in data["changes"]:
                if not valid(c):
                    i += 1
                    continue
                r = conn.execute("SELECT version FROM items WHERE sku=?", (c["sku"],)).fetchone()
                if r is not None and c["version"] <= r[0]:
                    s += 1
                    continue
                if c["op"] == "upsert":
                    conn.execute("INSERT OR REPLACE INTO items(sku,version,name,qty,present) VALUES(?,?,?,?,1)",
                                 (c["sku"], c["version"], c["name"], c["qty"]))
                else:
                    conn.execute("INSERT OR REPLACE INTO items(sku,version,name,qty,present) VALUES(?,?,NULL,NULL,0)",
                                 (c["sku"], c["version"]))
                a += 1
            nxt = data.get("next")
            newcur = cursor if nxt is None else str(nxt)
            conn.execute("INSERT OR REPLACE INTO meta(k,v) VALUES('cursor',?)", (newcur,))
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += a
        stale += s
        invalid += i
        if nxt is None:
            break
        cursor = newcur

    print("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    print(outcome)
    rows = conn.execute("SELECT sku, qty, name FROM items WHERE present=1").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in rows:
        print("%s %d %s" % (sku, qty, name))


