import os, json

def main():
    inp = os.environ["INPUT"]
    qpath = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    jobs = {}
    try:
        with open(qpath, "r", encoding="utf-8") as f:
            txt = f.read()
        if txt.strip():
            jobs = json.loads(txt).get("jobs", {})
    except FileNotFoundError:
        pass

    out = []
    try:
        with open(os.path.join(inp, "enqueue.jsonl"), "rb") as f:
            data = f.read().decode("utf-8", "replace")
    except FileNotFoundError:
        data = ""
    for n, line in enumerate(data.split("\n"), 1):
        s = line.strip()
        if not s:
            continue
        try:
            o = json.loads(s)
        except Exception:
            o = None
        if (not isinstance(o, dict) or not isinstance(o.get("id"), str)
                or not isinstance(o.get("priority"), int)
                or isinstance(o.get("priority"), bool)):
            out.append("invalid line %d" % n)
            continue
        if o["id"] in jobs:
            out.append("duplicate ID")
            continue
        jobs[o["id"]] = {"priority": o["priority"], "due": now,
                         "attempts": 0, "status": "pending"}

    try:
        with open(os.path.join(inp, "script.json"), "r", encoding="utf-8") as f:
            script = json.load(f)
        if not isinstance(script, dict):
            script = {}
    except Exception:
        script = {}

    cands = [(i, j) for i, j in jobs.items()
             if j["status"] == "pending" and j["due"] <= now]
    cands.sort(key=lambda t: (-t[1]["priority"], t[1]["due"], t[0].encode("utf-8")))
    for jid, j in cands[:5]:
        lst = script.get(jid)
        if isinstance(lst, list) and lst:
            res = lst[min(j["attempts"], len(lst) - 1)]
        else:
            res = "ok"
        j["attempts"] += 1
        if res == "fail":
            a = j["attempts"]
            if a >= 4:
                j["status"] = "dead"
                out.append("dead " + jid)
            else:
                secs = 60 * (2 ** (a - 1))
                j["due"] = now + secs * 1000
                out.append("retry %s in %d" % (jid, secs))
        else:
            j["status"] = "done"
            out.append("done " + jid)

    p = sum(1 for j in jobs.values() if j["status"] == "pending")
    d = sum(1 for j in jobs.values() if j["status"] == "done")
    x = sum(1 for j in jobs.values() if j["status"] == "dead")
    out.append("pending %d done %d dead %d" % (p, d, x))

    with open(qpath, "w", encoding="utf-8") as f:
        json.dump({"jobs": jobs}, f)
    print("\n".join(out))

