    except Exception:
        script = {}

    cands = [(i, j) for i, j in jobs.items()
             if j["status"] == "pending" and j["due"] <= now]
    cands.sort(key=lambda t: (-t[1]["priority"], t[1]["due"], t[0].encode("utf-8")))
    for jid, j in cands[:5]:
        lst = script.get(jid)
        if isinstance(lst, list) and lst:
            res = lst[min(j["attempts"], len(lst) - 1)]
        else:
            res = "ok"
        j["attempts"] += 1
        if res == "fail":
            a = j["attempts"]
            if a >= 4:
                j["status"] = "dead"
                out.append("dead " + jid)
            else:
                secs = 60 * (2 ** (a - 1))
                j["due"] = now + secs * 1000
                out.append("retry %s in %d" % (jid, secs))
        else:
            j["status"] = "done"
            out.append("done " + jid)

    p = sum(1 for j in jobs.values() if j["status"] == "pending")
    d = sum(1 for j in jobs.values() if j["status"] == "done")
    x = sum(1 for j in jobs.values() if j["status"] == "dead")
    out.append("pending %d done %d dead %d" % (p, d, x))

    with open(qpath, "w", encoding="utf-8") as f:
        json.dump({"jobs": jobs}, f)
    print("\n".join(out))

main()

import os, re, sys

sys.setrecursionlimit(10000)
LO, HI = -2**63, 2**63 - 1


class Err(Exception):
    pass


TOK = re.compile(r"[ \t\r\f\v]*(?:(\d+)|([A-Za-z_][A-Za-z0-9_]*)|([-+*/%^(),=]))")


def tokenize(s):
    toks = []
    pos = 0
    n = len(s)
    while True:
        while pos < n and s[pos] in " \t\r\f\v":
            pos += 1
        if pos >= n:
            break
        m = TOK.match(s, pos)
        if not m:
            raise Err("syntax error")
        if m.group(1) is not None:
            toks.append(("int", m.group(1)))
        elif m.group(2) is not None:
            toks.append(("name", m.group(2)))
        else:
            toks.append(("op", m.group(3)))
        pos = m.end()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else (None, None)

    def isop(self, v):
        return self.peek() == ("op", v)

    def expect(self, v):
        if not self.isop(v):
            raise Err("syntax error")
        self.i += 1

    def expr(self):
        node = self.term()
        while self.isop("+") or self.isop("-"):
            op = self.peek()[1]
            self.i += 1
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.peek()[0] == "op" and self.peek()[1] in "*/%":
            op = self.peek()[1]
            self.i += 1
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.isop("-"):
            self.i += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.isop("^"):
            self.i += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.i += 1
            return ("int", int(v))
        if k == "name":
            self.i += 1
            if self.isop("("):
                self.i += 1
                args = [self.expr()]
                while self.isop(","):
                    self.i += 1
                    args.append(self.expr())
                self.expect(")")
                return ("call", v, args)
            return ("var", v)
        if self.isop("("):
            self.i += 1
            e = self.expr()
            self.expect(")")
            return e
        raise Err("syntax error")


def chk(v):
    if v < LO or v > HI:
        raise Err("overflow")
    return v


ARITY = {"min": 2, "max": 2, "abs": 1}


def ev(n, env):
    k = n[0]
    if k == "int":
        return chk(n[1])
    if k == "var":
        if n[1] not in env:
            raise Err("unknown variable " + n[1])
        return env[n[1]]
    if k == "neg":
        return chk(-ev(n[1], env))
    if k == "call":
        name, args = n[1], n[2]
        if name not in ARITY:
            raise Err("unknown function " + name)
        if len(args) != ARITY[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    op = n[1]
    a = ev(n[2], env)
    b = ev(n[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return chk(q)
        return chk(a - q * b)
    if b < 0:
        raise Err("negative exponent")
    if a in (0, 1):
        return 1 if b == 0 else a
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise Err("overflow")
    return chk(a ** b)


def run_line(s, env):
    toks = tokenize(s)
    name = None
    if toks and toks[0] == ("name", "let"):
        if len(toks) < 4 or toks[1][0] != "name" or toks[2] != ("op", "="):
            raise Err("syntax error")
        name = toks[1][1]
        p = Parser(toks[3:])
    else:
        p = Parser(toks)
    tree = p.expr()
    if p.i != len(p.t):
        raise Err("syntax error")
    v = ev(tree, env)
    if name is not None:
        env[name] = v
        return "%s = %d" % (name, v)
    return str(v)


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "program.txt"), "rb") as f:
        text = f.read().decode("utf-8", "replace")
    env = {}
    out = []
    for i, line in enumerate(text.split("\n"), 1):
        if not line.strip():
            continue
        try:
            r = run_line(line, env)
            out.append("%d: %s" % (i, r))
        except Err as e:
            out.append("%d: error: %s" % (i, e))
        except RecursionError:
            out.append("%d: error: syntax error" % i)
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()

import os, sys, json, hmac, hashlib, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DBP = os.environ["DB"]
SECRETS = os.environ["SECRETS"]
LOG = os.environ["LOG"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()
TYPES = {"subscription.created", "subscription.activated",
         "payment.failed", "subscription.canceled"}
TRANS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}


def connect():
    c = sqlite3.connect(DBP, isolation_level=None, timeout=30)
    c.executescript("""
    CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS subs(id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS history(sub TEXT NOT NULL, n INTEGER NOT NULL, state TEXT NOT NULL, PRIMARY KEY(sub, n));
    CREATE TABLE IF NOT EXISTS queued(sub TEXT NOT NULL, seq INTEGER NOT NULL, id TEXT NOT NULL, type TEXT NOT NULL, PRIMARY KEY(sub, seq));
    """)
    return c


def log(line):
    with open(LOG, "a") as f:
        f.write(line + "\n")


def secret():
    with open(os.path.join(SECRETS, "webhook.key"), "rb") as f:
        d = f.read()
    if d.endswith(b"\n"):
        d = d[:-1]
    return d


def handle_event(ev):
    """returns (status, body, loglines)"""
    logs = []
    c = connect()
    try:
        c.execute("BEGIN IMMEDIATE")
        if c.execute("SELECT 1 FROM events WHERE id=?", (ev["id"],)).fetchone():
            c.execute("COMMIT")
            return 200, {"status": "duplicate"}, logs
        c.execute("INSERT INTO events(id) VALUES(?)", (ev["id"],))
        sub = ev["subscription"]
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sub,)).fetchone()
        state, last = row if row else ("none", 0)
        seq = ev["seq"]
        if seq <= last:
            c.execute("COMMIT")
            return 200, {"status": "stale"}, logs
        if seq > last + 1:
            c.execute("INSERT OR IGNORE INTO queued(sub,seq,id,type) VALUES(?,?,?,?)",
                      (sub, seq, ev["id"], ev["type"]))
            c.execute("COMMIT")
            return 202, {"status": "queued"}, logs
        cur_id, cur_type = ev["id"], ev["type"]
        k = 0
        hn = c.execute("SELECT COALESCE(MAX(n),0) FROM history WHERE sub=?", (sub,)).fetchone()[0]
        while True:
            frm, to = TRANS[cur_type]
            if state in frm:
                state = to
                hn += 1
                c.execute("INSERT INTO history(sub,n,state) VALUES(?,?,?)", (sub, hn, state))
            else:
                logs.append("invalid transition " + cur_id)
            last += 1
            k += 1
            nxt = c.execute("SELECT id,type FROM queued WHERE sub=? AND seq=?",
                            (sub, last + 1)).fetchone()
            if not nxt:
                break
            c.execute("DELETE FROM queued WHERE sub=? AND seq=?", (sub, last + 1))
            cur_id, cur_type = nxt
        c.execute("INSERT OR REPLACE INTO subs(id,state,seq) VALUES(?,?,?)", (sub, state, last))
        c.execute("COMMIT")
        return 200, {"status": "applied", "applied": k}, logs
    except Exception:
        try:
            c.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        c.close()


def get_sub(sid):
    c = connect()
    try:
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sid,)).fetchone()
        if not row or row[1] < 1:
            return None
        h = [r[0] for r in c.execute("SELECT state FROM history WHERE sub=? ORDER BY n", (sid,))]
        return {"id": sid, "state": row[0], "seq": row[1], "history": h}
    finally:
        c.close()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def log_message(self, *a):
        pass

    def do_GET(self):
        path = urlsplit(self.path).path
        if path.startswith("/subscriptions/") and len(path) > len("/subscriptions/"):
            sid = unquote(path[len("/subscriptions/"):])
            with LOCK:
                r = get_sub(sid)
            if r is not None:
                return self.send(200, r)
        self.send(404, {"error": "not found"})

    def do_POST(self):
        n = int(self.headers.get("content-length") or 0)
        body = self.rfile.read(n) if n > 0 else b""
        path = urlsplit(self.path).path
        if path != "/webhooks":
            return self.send(404, {"error": "not found"})
        sig = self.headers.get("x-signature") or ""
        exp = "sha256=" + hashlib.sha256(secret() + b"." + body).hexdigest()
        if not hmac.compare_digest(sig.encode("utf-8", "replace"), exp.encode()):
            log("rejected signature")
            return self.send(401, {"error": "bad signature"})
        try:
            ev = json.loads(body.decode("utf-8"))
        except Exception:
            ev = None
        ok = (isinstance(ev, dict)
              and isinstance(ev.get("id"), str)
              and isinstance(ev.get("type"), str) and ev["type"] in TYPES
              and isinstance(ev.get("subscription"), str)
              and isinstance(ev.get("seq"), int) and not isinstance(ev.get("seq"), bool)
              and ev["seq"] >= 1)
        if not ok:
            return self.send(400, {"error": "invalid event"})
        with LOCK:
            code, obj, logs = handle_event(ev)
            for l in logs:
                log(l)
        self.send(code, obj)

    do_PUT = do_DELETE = do_PATCH = do_HEAD = lambda self: self.send(404, {"error": "not found"})


if __name__ == "__main__":
    connect().close()
    ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
